'use strict';
const C_PRODUCTS=[...window.PLATFORM_PRODUCTS,...window.PRODUCTS];
const C_NAV=[['/arquitetura/','Arquitetura','Princípios e camadas'],['/capacidades/','Building blocks','Capacidades modulares'],['/studio/','Studio','Construir e iterar'],['/workflows/','Workflows','Orquestração de processos'],['/agentes/','Agentes IA','Contexto e ferramentas'],['/governanca/','Governança','Permissões e evidências'],['/desenvolvedores/','Documentação','Guias e referências']];
const C_CORE=[['/','Home'],['/visao/','Visão'],...C_NAV.map(x=>x.slice(0,2)),['/composicoes/','Composições'],['/ecossistema/','Ecossistema'],['/interfaces/','Interfaces'],['/perspectivas/','Perspectivas'],['/press-kit/','Press-kit'],['/contato/','Contato'],['/fontes/','Fontes'],['/mapa/','Mapa do site']];
const C_ESSAYS=[{slug:'construir-por-composicao',title:'Por que construir por composição?',tag:'Arquitetura e produto',intro:'Produtos mudam. As responsabilidades que os sustentam podem encontrar uma base comum.',paragraphs:[['Uma capacidade inteira','Uma identidade, uma política de decisão e uma entrega de evento resolvem problemas diferentes. A composição começa quando cada parte conhece seu papel e apresenta um contrato claro.'],['Uma base, vários contextos','Uma agenda participa de uma consulta, de uma entrevista ou de uma reunião. O produto traz o contexto; a capacidade preserva a responsabilidade.'],['Conexões que você pode entender','Quando quem busca dados e quem avalia uma política são responsabilidades distintas, o caminho até uma resposta fica mais legível. A composição precisa preservar essas fronteiras.']]},{slug:'autonomia-responsabilidade',title:'Onde termina a autonomia?',tag:'Agentes e responsabilidade',intro:'Ferramentas ampliam o que um agente consegue fazer. Limites tornam essa atuação legível.',paragraphs:[['Um papel definido','Objetivo, conhecimento e ferramentas determinam a atuação de um agente. A autonomia tem um contexto: o que ele pode consultar, registrar e encaminhar.'],['Uma pessoa responsável','No Med, o registro depende da liberação do profissional. No Recrutamento, o parecer exige aprovação. No Jurídico, a análise permanece com o advogado.'],['Evidência acompanha a ação','Permissões, registros e versões ajudam a compreender quem agiu e o que orientou o resultado. Isso deve aparecer no contrato e na experiência.']]},{slug:'regra-legivel',title:'Uma regra que você consegue ler.',tag:'Decisão e arquitetura',intro:'Separar a política da jornada torna suas responsabilidades mais claras.',paragraphs:[['A política tem uma versão','O Decision Engine publica e executa tabelas DMN versionadas. O resultado registra a política utilizada.'],['O fluxo tem outro papel','A Decision Platform reúne fontes e organiza a esteira. Motor e orquestração participam da mesma jornada com responsabilidades próprias.']]}];
const ce=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ca=(u,t,cls='text-link')=>`<a class="${cls}" href="${u}"${u.startsWith('https:')?' target="_blank" rel="noopener"':''}>${t}<span aria-hidden="true">↗</span></a>`;
const cl=t=>`<span class="label">${t}</span>`;
const ci=(file,alt,cls='',priority=false)=>`<img class="${cls}" src="/assets/connection/${file}" alt="${alt}" ${priority?'fetchpriority="high"':'loading="lazy"'}>`;
const cs=(s,cls='')=>`<section class="section ${cls}"><div class="wrap">${s}</div></section>`;
function cLogo(){return `<a class="wordmark" href="/" aria-label="Catalisa — início">catalisa<span aria-hidden="true"></span></a>`}
function cHeader(){return `<a href="#main" class="skip-link">Pular para o conteúdo</a><header class="site-header"><div class="wrap header-row">${cLogo()}<nav class="top-nav" aria-label="Principal"><button class="nav-toggle" data-menu="platform" aria-expanded="false" aria-controls="menu-platform">Plataforma</button><a href="/ecossistema/">Ecossistema</a><a href="/perspectivas/">Perspectivas</a></nav><div class="header-right"><a href="/visao/">Visão</a><button class="menu-trigger" data-menu="all" aria-expanded="false" aria-controls="menu-all"><span class="mobile-menu-label">Menu</span><i aria-hidden="true"></i><span class="sr-only">Abrir navegação</span></button></div></div><div id="menu-platform" class="mega-menu" hidden><div class="wrap mega-inner"><div><h2>Uma base<br>para construir.</h2><p>Capacidades modulares para conectar pessoas, dados e agentes.</p>${ca('/arquitetura/','Explorar a plataforma')}</div>${ci('hero.webp','Escultura modular em roxo e laranja','menu-art')}<nav aria-label="Plataforma">${C_NAV.map(([u,n,d])=>`<a href="${u}">${n}<small>${d}</small></a>`).join('')}</nav></div></div><div id="menu-all" class="mega-menu" hidden><div class="wrap all-menu"><div>${cl('Plataforma')}<nav aria-label="Plataforma completa">${C_NAV.map(([u,n])=>ca(u,n)).join('')}</nav></div><div>${cl('Ecossistema')}<nav aria-label="Produtos">${C_PRODUCTS.map(p=>ca('/ecossistema/'+p.slug+'/',p.name)).join('')}</nav></div><div>${cl('Catalisa')}<nav aria-label="Marca e recursos">${[['/visao/','Visão'],['/perspectivas/','Perspectivas'],['/interfaces/','Interfaces'],['/press-kit/','Press-kit'],['/contato/','Contato']].map(([u,n])=>ca(u,n)).join('')}</nav></div></div></div></header>`}
function cFooter(){return `<footer class="site-footer"><div class="wrap">${cLogo()}<nav aria-label="Rodapé">${[['/arquitetura/','Plataforma'],['/ecossistema/','Ecossistema'],['https://docs.catalisa.app/','Documentação'],['/press-kit/','Press-kit'],['/contato/','Contato']].map(([u,n])=>`<a href="${u}">${n}</a>`).join('')}</nav><small>© Catalisa</small></div></footer>`}
function cSignal(){let paths='';for(let i=0;i<110;i++){const x=(i*71)%540,y=80+(i*37)%190;paths+=`<line x1="${x}" y1="${y}" x2="${x+2}" y2="${y+2}" stroke="#574b5c" stroke-opacity="${.25+i%5*.1}"/>`;}return `<svg class="signal-art" viewBox="0 0 1440 330" role="img" aria-label="Fragmentos se organizam em caminhos conectados"><g>${paths}${Array.from({length:290},(_,i)=>`<circle cx="${(i*113)%850}" cy="${165+Math.sin(i*47)*Math.max(8,110-(i*113)%850*.12)}" r="${.8+i%3*.3}" fill="#5a4c63" opacity=".5"/>`).join('')}</g><circle cx="1200" cy="145" r="58" fill="#ff7f36"/><g fill="none" stroke-width="1.6">${[0,1,2,3,4].map((i)=>`<path class="signal-path" style="--delay:${i*.1}s" stroke="${i===3?'#e87d38':'#8966ad'}" d="M360 ${135+i*14} C650 ${230-i*30},780 ${30+i*50},940 ${90+i*30} S1110 ${30+i*40},1200 ${110+i*23} S1330 ${145+i*20},1440 ${145+i*20}"/>`).join('')}</g></svg>`}
function cAccordion(){return `<div class="architecture-accordion">${[['Identidade','Quem acessa, em qual organização e com quais permissões.','iam','Explore o IAM'],['Dados','Informações organizadas por contexto, com responsabilidades e contratos próprios.','data-store','Explore Data Store'],['Decisão','Regras de negócio em tabelas DMN, publicadas e versionadas.','decision-engine','Explore Decision Engine'],['Canais','Conversa e vídeo conectam a experiência às capacidades da plataforma.','wpp-business','Explore WPP Business']].map(([n,d,s,l],i)=>`<details ${i===0?'open':''} name="architecture-layers"><summary>${n}<span aria-hidden="true"></span></summary><div><p>${d}</p>${ca('/capacidades/'+s+'/',l)}</div></details>`).join('')}</div>`}
function cBankingVisual(){return `<div class="banking-photo" aria-hidden="true"><img src="/assets/connection/banking.webp" alt="" loading="lazy"></div>`}
function cCreditVisual(){return `<svg class="credit-installation" viewBox="0 0 340 340" aria-hidden="true"><defs><filter id="ring-shadow"><feDropShadow dx="10" dy="14" stdDeviation="7" flood-opacity=".3"/></filter><linearGradient id="ring-orange" x2="1" y2="1"><stop stop-color="#ffa438"/><stop offset=".7" stop-color="#f17a24"/><stop offset="1" stop-color="#ce5317"/></linearGradient></defs><g stroke="#bda4d3" stroke-width=".6" opacity=".45" fill="none"><path d="M50 250H290V100M80 300V40M240 310V50M40 280L280 40M50 150H300"/><circle cx="184" cy="173" r="104"/></g><g filter="url(#ring-shadow)" fill="none" stroke-width="37"><circle cx="184" cy="173" r="87" stroke="#68418e"/><path d="M184 86A87 87 0 0 1 184 260" stroke="url(#ring-orange)"/><path d="M151 254A87 87 0 0 1 126 238" stroke="#f5f0e8"/></g><g fill="#fac23a"><circle cx="80" cy="279" r="3"/><circle cx="240" cy="108" r="3"/></g></svg>`}
function cProductExhibit(){return `<div class="product-exhibition"><a class="banking-feature" href="/ecossistema/banking/"><div class="feature-copy"><h3>Banking<br>Platform</h3><p>Experiências bancárias<br>conectadas à operação.</p><span class="text-link">Explorar ↗</span><small>App · Desktop · Console</small></div>${cBankingVisual()}</a><a class="credit-feature" href="/ecossistema/credit/"><div class="feature-copy"><h3>Credit<br>Platform</h3><p>Da entrada da proposta<br>ao acompanhamento<br>da carteira.</p><span class="text-link">Explorar ↗</span><small>Originação · Política · Operação</small></div>${cCreditVisual()}</a></div><nav class="product-index" aria-label="Outros produtos">${C_PRODUCTS.filter(p=>!['banking','credit'].includes(p.slug)).map(p=>ca('/ecossistema/'+p.slug+'/',p.name)).join('')}</nav>`}
function cFilmDialog(){return `<dialog id="concept-film" class="film-dialog"><div class="dialog-top"><span>Estudo de composição</span><button data-close-film aria-label="Fechar filme">Fechar ×</button></div><div class="film-stage">${ci('hero.webp','Peças conectadas — estudo visual','film-assembled')}${ci('architecture.webp','Peças independentes — estudo visual','film-exploded')}<span class="film-word">Peças independentes.<br>Possibilidades conectadas.</span></div><div class="dialog-bottom"><span>Filme conceitual · animação de imagens · sem áudio</span><button data-toggle-film aria-pressed="false">Pausar</button></div></dialog>`}
function cHome(){return `<section class="home-hero"><div class="wrap hero-inner"><div class="hero-copy"><h1>A forma segue<br>a conexão.</h1><p>Uma plataforma de capacidades<br class="desktop-break"> combináveis para criar produtos,<br class="desktop-break"> conectar operações e transformar<br class="desktop-break"> ideias em sistemas.</p>${ca('/arquitetura/','Conheça a plataforma')}</div>${ci('financial-city.webp','Cidade financeira modular: edifícios roxos conectados por pontes laranja sobre uma base compartilhada','hero-sculpture',true)}<span class="hero-caption">01 /<br>PEÇAS INDEPENDENTES.<br>POSSIBILIDADES<br>CONECTADAS.</span></div></section><section class="logic-section"><div class="wrap logic-copy"><h2>A complexidade pode<br>encontrar outra lógica.</h2><p>Identidade, dados, decisões e canais.<br>Capacidades com responsabilidades<br>próprias, conectadas por uma base comum.</p></div>${cSignal()}</section><section class="architecture-section" id="arquitetura"><div class="wrap architecture-inner"><div class="architecture-image">${ci('architecture.webp','Estudo técnico das peças separadas de uma escultura modular')}</div><div class="architecture-content"><h2>Independentes na função.<br>Conectadas na arquitetura.</h2>${cAccordion()}${ca('/capacidades/','Ver building blocks')}</div></div></section><section class="ecosystem-section"><div class="wrap">${cl('Ecossistema')}<h2>O mesmo fundamento.<br>Outras formas de operar.</h2>${cProductExhibit()}</div></section><section class="studio-cinema">${ci('studio.webp','Arquitetura monumental roxa com passagem iluminada em laranja','studio-background')}<div class="wrap"><div class="studio-copy"><h2>Da intenção<br>ao sistema.</h2><p>No Studio, a descrição encontra<br>contexto, ferramentas e fluxos.</p><button class="film-trigger" data-open-film><span aria-hidden="true">▶</span>Filme conceitual</button>${ca('/studio/','Conheça o Studio')}</div></div></section><section class="home-perspectives"><div class="wrap perspectives-inner"><div>${cl('Perspectivas')}<h2>Pensar também<br>é construir.</h2></div>${C_ESSAYS.slice(0,2).map(e=>`<a href="/perspectivas/${e.slug}/"><h3>${e.title}</h3><p>${e.tag}</p><span aria-hidden="true">→</span></a>`).join('')}</div></section><section class="home-contact"><div class="wrap"><h2>Vamos conectar<br>o próximo?</h2>${ca('/contato/','Converse com a Catalisa')}</div><span class="contact-ring" aria-hidden="true"></span></section>${cFilmDialog()}`}
function cIntro(tag,title,text='',image=''){return `<section class="page-intro"><div class="wrap">${cl(tag)}<h1>${title}</h1>${text?`<p>${text}</p>`:''}${image?ci(image,'Estudo de composição Catalisa','intro-art'):''}</div></section>`}
function cNext(u,t){return cs(`<a class="next-page" href="${u}"><div>${cl('Continue explorando')}<h2>${t}</h2></div><span>↗</span></a>`,'next-section')}
function cRows(items){return `<div class="content-rows">${items.map(([n,t],i)=>`<div><span class="label">0${i+1}</span><h3>${n}</h3><p>${t}</p></div>`).join('')}</div>`}
function cBlockList(slugs,blocks){return `<div class="block-list">${(slugs?slugs.map(s=>blocks.find(b=>b.slug===s)).filter(Boolean):blocks).map(b=>`<a href="/capacidades/${b.slug}/" data-block data-category="${ce(b.category)}" data-status="${ce(b.status)}" data-search="${ce((b.name+' '+b.tagline+' '+b.category).toLowerCase())}"><span class="label">${ce(b.category)}</span><h3>${ce(b.name)}</h3><p>${ce(b.tagline)}</p><span class="block-status">${ce(b.status)}</span><i aria-hidden="true">↗</i></a>`).join('')}</div>`}
function cProduct(p,blocks){const bank=p.slug==='banking',credit=p.slug==='credit';return `<nav class="wrap breadcrumb" aria-label="Localização"><a href="/ecossistema/">Ecossistema</a><span>/</span>${ce(p.name)}</nav>`+cIntro('Construído com Catalisa',ce(p.name),ce(p.description))+cs(`<div class="product-lead"><div><h2>${p.principle}</h2><p>${p.principleText}</p>${ca(p.source,'Referência do produto')}</div><div class="product-art-panel ${credit?'violet':''}">${bank?cBankingVisual():credit?cCreditVisual():ci('hero.webp','Capacidades conectadas em um novo contexto')}</div></div>`)+cs(`${cl('A jornada')}${cRows(p.steps)}`)+cs(`<h2>O que esta composição organiza.</h2>${cRows(p.features)}`)+(bank||credit?cs(`<h2>Interfaces em contexto.</h2><p class="section-note">Capturas do material de referência, com dados de exemplo. Clique para ampliar.</p><div class="screenshot-grid">${window.SCREENSHOTS.filter(s=>s.product===p.slug).map(s=>`<button class="screenshot-button" data-image="/assets/screens/${s.file}" data-caption="${ce(s.title+' — '+s.desc)}"><img src="/assets/screens/${s.file}" alt="${ce(s.title)}" loading="lazy"><span>${ce(s.title)} ↗</span></button>`).join('')}</div>`):'')+cs(`<h2>As peças por trás da experiência.</h2>${cBlockList(p.blocks,blocks)}`)+cs(`<div class="reading"><h2>Responsabilidade e contexto.</h2><p>${p.boundary}</p>${ca(p.source,'Consulte a fonte completa')}</div>`)+cNext('/ecossistema/','Outras expressões da mesma base.')}
function cArchitecture(){return cIntro('Plataforma / Arquitetura','Independentes na função.<br>Conectadas na arquitetura.','Uma capacidade resolve um problema. A composição conecta essas responsabilidades.')+`<section class="architecture-section"><div class="wrap architecture-inner"><div class="architecture-image">${ci('architecture.webp','Peças arquiteturais independentes em um estudo explodido')}</div><div class="architecture-content">${cAccordion()}${ca('/capacidades/','Explore os contratos')}</div></div></section>`+cs(`<div class="reading-pair"><h2>A esteira busca.<br>O motor decide.</h2><div><p>Decision Platform reúne as fontes declaradas. Decision Engine avalia a política DMN publicada. A conexão preserva o papel de cada capacidade.</p>${ca('/capacidades/decision-platform/','Decision Platform')}${ca('/capacidades/decision-engine/','Decision Engine')}</div></div>`)+cNext('/composicoes/','A combinação muda o resultado.')}
function cCatalog(blocks){return cIntro('Plataforma / Building blocks','Encontre a peça certa.','Capacidades com contratos, responsabilidades e estágios próprios.')+cs(`<div class="catalog-toolbar"><label class="sr-only" for="block-query">Buscar capacidade</label><input id="block-query" type="search" placeholder="Busque uma capacidade…"><select id="category-query" aria-label="Filtrar por domínio"><option value="">Todos os domínios</option>${[...new Set(blocks.map(b=>b.category))].sort().map(c=>`<option>${ce(c)}</option>`).join('')}</select><select id="status-query" aria-label="Filtrar por estágio"><option value="">Todos os estágios</option><option>Produção</option><option>Beta</option><option>Alpha</option></select></div><p class="section-note" id="catalog-count" role="status">${blocks.length} capacidades nesta seleção editorial</p>${cBlockList(null,blocks)}<p id="empty-catalog" hidden>Nenhuma capacidade encontrada. Tente outro termo.</p>${ca('https://docs.catalisa.app/blocks/','Consulte o catálogo técnico atualizado')}`)}
function cBlock(b,blocks){return `<nav class="wrap breadcrumb" aria-label="Localização"><a href="/capacidades/">Building blocks</a><span>/</span>${ce(b.name)}</nav>`+cIntro(b.category,ce(b.name),ce(b.tagline))+cs(`<div class="doc-layout"><aside><span class="status-dot">${ce(b.status)}</span><nav aria-label="Nesta capacidade">${b.sections.map(s=>`<a href="#${s.id}">${s.title}</a>`).join('')}</nav>${ca(b.source,'Contrato completo')}</aside><article>${b.sections.map(s=>`<section class="doc-section" id="${s.id}"><h2>${s.title}</h2>${s.html}</section>`).join('')}<p class="section-note">Resumo da documentação pública consultada. Contrato e estágio atualizados permanecem na referência completa.</p>${ca(b.source,'Documentação oficial')}</article></div>`)+cNext('/capacidades/','Volte ao conjunto de capacidades.')}
const C_STUDIES={studio:['Studio','Da intenção<br>ao sistema.','A descrição encontra contexto, ferramentas e fluxos.','O Studio transforma descrições em linguagem natural em especificações de agentes e automações. A composição organiza os blocos que participam da jornada.',[['Descreva','Comece por uma necessidade em linguagem natural ou por um template.'],['Refine','Contexto, ferramentas e comportamento esperado encontram uma especificação.'],['Componha','O workflow organiza as capacidades e as responsabilidades.']],'https://catalisa.io/studio/'],workflows:['Workflows','O evento encontra<br>o próximo passo.','Gatilhos, condições e ações tornam o trabalho legível.','Mensagens, webhooks e agendamentos podem iniciar uma jornada. Condições orientam o caminho; capacidades realizam o trabalho.',[['Evento','Uma ocorrência inicia a execução.'],['Condição','Uma regra determina por onde continuar.'],['Ação','Uma capacidade consulta, transforma, registra ou entrega informação.']],'https://catalisa.io/workflows/'],agentes:['Agentes IA','Contexto para entender.<br>Ferramentas para agir.','A conversa se conecta à operação.','Agentes combinam instruções, conhecimento e ferramentas para participar de jornadas. O objetivo, as permissões e os limites definem o que cada agente pode realizar.',[['Papel','Objetivo, contexto e limites orientam a atuação.'],['Conhecimento','O acervo da organização dá contexto às respostas.'],['Ferramentas','Capacidades conectadas permitem agir sobre a operação.']],'https://catalisa.io/ai-agents/']};
function cStudy(key){const [name,title,desc,text,items,url]=C_STUDIES[key];return cIntro('Plataforma / '+name,title,desc)+`<section class="study-wide">${ci('studio.webp','Passagem arquitetural em roxo e laranja')}</section>`+cs(`<div class="reading-pair"><h2>Uma intenção<br>encontra estrutura.</h2><p>${text}</p></div>${cRows(items)}`)+cs(`<div class="reading">${cl('Exemplo ilustrativo')}<h2>“Organize o atendimento.<br>Encontre um horário<br>na agenda real.”</h2><p>Mensagem → contexto → agenda → registro.</p>${ca('/composicoes/','Explore a composição')}${ca(url,'Referência oficial')}</div>`)+cNext('/governanca/','Autonomia pede responsabilidade.')}
function cArticle(e){return cIntro(e.tag,e.title,e.intro)+cs(`<article class="reading article-reading"><p class="section-note">Perspectiva editorial proposta para este site.</p>${e.paragraphs.map(([h,t])=>`<h2>${h}</h2><p>${t}</p>`).join('')}${ca('https://docs.catalisa.app/','Referências na documentação')}</article>`)+cNext('/perspectivas/','Continue a leitura.')}
function cPage(route,blocks){if(route==='/')return cHome();const p=C_PRODUCTS.find(p=>route==='/ecossistema/'+p.slug+'/');if(p)return cProduct(p,blocks);const b=blocks.find(b=>route==='/capacidades/'+b.slug+'/');if(b)return cBlock(b,blocks);const e=C_ESSAYS.find(e=>route==='/perspectivas/'+e.slug+'/');if(e)return cArticle(e);const key=route.split('/')[1];if(C_STUDIES[key])return cStudy(key);
if(route==='/arquitetura/')return cArchitecture();
if(route==='/capacidades/')return cCatalog(blocks);
if(route==='/ecossistema/')return cIntro('Ecossistema','O mesmo fundamento.<br>Outras formas de operar.','Produtos que dão expressão própria às capacidades da Catalisa.')+cs(cProductExhibit())+cs(`<div class="product-directory">${C_PRODUCTS.map(p=>`<a href="/ecossistema/${p.slug}/">${cl(p.category)}<h2>${p.name}</h2><p>${p.description}</p><span>Explore a composição ↗</span></a>`).join('')}</div>`);
if(route==='/perspectivas/')return cIntro('Perspectivas','Pensar também<br>é construir.','Arquitetura, composição e responsabilidade.')+cs(`<div class="essay-index">${C_ESSAYS.map(e=>`<a href="/perspectivas/${e.slug}/">${cl(e.tag)}<h2>${e.title}</h2><p>${e.intro}</p><span>Leia a perspectiva ↗</span></a>`).join('')}</div>`);
if(route==='/visao/')return cIntro('Visão da Catalisa','A forma segue<br>a conexão.','Uma plataforma de capacidades combináveis para transformar ideias em sistemas.')+cs(`<div class="reading-pair"><h2>A complexidade pode<br>encontrar outra lógica.</h2><p>Dados, regras e integrações sustentam cada interação de uma operação. A Catalisa organiza essas responsabilidades em capacidades que podem ser compreendidas, conectadas e reutilizadas.</p></div>${cSignal()}`)+cs(cRows([['Clareza','Cada capacidade explica o que faz e onde termina.'],['Composição','Conectar capacidades permite construir jornadas próprias para cada contexto.'],['Responsabilidade','Permissões, registros e decisões humanas têm lugar explícito nos produtos.']]))+cNext('/arquitetura/','Conheça a estrutura por trás da ideia.');
if(route==='/governanca/')return cIntro('Plataforma / Governança','Confiança se constrói<br>no detalhe.','Quem pode agir, o que aconteceu e qual versão orientou o resultado.')+cs(cRows([['Identidade','O IAM organiza usuários, organizações e permissões.'],['Rastreabilidade','Decision Engine registra a versão da política utilizada na execução.'],['Evidência','Biometrics associa verificações e evidência assinada à sessão.'],['Responsabilidade humana','Med, Jurídico e Recrutamento preservam a revisão profissional em etapas próprias.']]))+cs(`<h2>O estágio também faz parte do contrato.</h2><p>Produção, Beta e Alpha indicam diferentes níveis de maturidade. Consulte o escopo e os limites na referência de cada capacidade.</p>${cBlockList(['iam','audit-trail','decision-engine','biometrics'],blocks)}`)+cNext('/desenvolvedores/','Explore os contratos.');
if(route==='/desenvolvedores/')return cIntro('Desenvolvedores','Comece pela<br>responsabilidade.','Encontre a capacidade. Confira o contrato. Construa a integração.')+cs(`<div class="reading-pair"><h2>APIs, eventos<br>e fronteiras.</h2><div><p>Cada building block documenta seu domínio e as operações que oferece. Identidade, permissões, estágio e limites fazem parte da escolha.</p>${ca('https://docs.catalisa.app/','Abrir documentação')}${ca('/capacidades/','Explore as capacidades')}</div></div>`)+cs(cRows([['Identidade','IAM e API Keys organizam acesso e credenciais.'],['Captura e decisão','Biometrics organiza a sessão de verificação.'],['Mídia e eventos','File Storage e Webhooks Engine têm contratos próprios.']]))+cNext('/capacidades/','Encontre a peça certa.');
if(route==='/composicoes/')return cIntro('Composições','A conexão muda<br>o resultado.','Jornadas ilustrativas conectam capacidades reais, preservando suas fronteiras.')+cs(`<div class="composition-selector"><div role="tablist" aria-label="Composições"><button role="tab" aria-selected="true" data-composition="0">Atendimento</button><button role="tab" aria-selected="false" data-composition="1">Identidade</button><button role="tab" aria-selected="false" data-composition="2">Decisão</button></div><div id="composition-example" role="tabpanel">${cComposition(0)}</div></div>`)+cNext('/capacidades/','Explore as peças da composição.');
if(route==='/interfaces/')return cIntro('Material de referência','A arquitetura<br>vista por quem usa.','Aplicativo, desktop, console e mesa. Dados de exemplo; materiais em estágios diferentes.')+cs(`<div class="screenshot-grid">${window.SCREENSHOTS.map(s=>`<button class="screenshot-button" data-image="/assets/screens/${s.file}" data-caption="${ce(s.title+' — '+s.desc)}"><img src="/assets/screens/${s.file}" alt="${ce(s.title)}" loading="lazy"><span>${ce(s.title)} ↗</span></button>`).join('')}</div>`);
if(route==='/contato/')return cIntro('Contato','Vamos conectar<br>o próximo?','Uma conversa sobre a ideia, a arquitetura e o que você quer construir.')+cs(`<div class="reading"><p>Encontre o canal de contato e o agendamento no site oficial da Catalisa.</p>${ca('https://catalisa.io/','Converse com a Catalisa','button')}<p class="section-note">Você será direcionado ao canal oficial.</p></div>`);
if(route==='/press-kit/')return cIntro('Marca / Press-kit','Uma linguagem<br>que conecta.','Recursos oficiais de identidade da Catalisa.')+cs(`<div class="brand-logo-panel">${cLogo()}</div><div class="brand-colors">${[['#734B9C','Roxo'],['#FDC234','Amarelo'],['#1A1D23','Grafite'],['#FFFFFF','Branco']].map(([h,n])=>`<div><span style="background:${h}"></span><h3>${n}</h3><p>${h}</p></div>`).join('')}</div><p>Inter é a tipografia principal. O laranja aparece como acento expressivo nesta proposta.</p>${ca('https://catalisa.io/press-kit/','Baixe os recursos oficiais')}`);
if(route==='/fontes/')return cIntro('Referências','A base do conteúdo.','Fontes oficiais e materiais de referência usados nesta proposta.')+cs(`<div class="reference-list">${[['https://catalisa.io/','Site institucional'],['https://docs.catalisa.app/','Documentação dos building blocks'],['https://catalisa.io/press-kit/','Press-kit'],['https://github.com/catalisaio/wpp.bb.catalisa.io','Repositório indicado — acesso conforme permissões']].map(([u,n])=>ca(u,n)).join('')}${C_PRODUCTS.filter(p=>p.source.startsWith('https:')).map(p=>ca(p.source,p.name)).join('')}</div>`);
if(route==='/mapa/')return cIntro('Navegação','Todas as conexões.','Explore a plataforma, o ecossistema e as capacidades.')+cs(`<div class="site-map"><div>${C_CORE.map(([u,n])=>ca(u,n)).join('')}</div><div>${C_PRODUCTS.map(p=>ca('/ecossistema/'+p.slug+'/',p.name)).join('')}</div><div>${blocks.map(b=>ca('/capacidades/'+b.slug+'/',b.name)).join('')}</div></div>`);
return cIntro('Página não encontrada','Vamos encontrar<br>outro caminho.')+cs(ca('/mapa/','Explore o mapa'))}
function cComposition(i){const d=[['Uma conversa conecta capacidades.','A mensagem encontra contexto, consulta disponibilidade e acompanha o registro.',['Mensagem','Contexto','Agenda','Registro']],[ 'Verificar é uma composição.','A sessão organiza a captura e a decisão. Mídia e eventos mantêm responsabilidades próprias.',['Sessão','Captura','Verificação','Evidência']],['Dados e regras têm papéis diferentes.','A esteira reúne as fontes. O motor aplica a política publicada e versionada.',['Entrada','Fontes','Política','Resposta']]][i];return `<div class="composition-content"><div>${ci('architecture.webp','Composição ilustrativa das capacidades')}</div><div>${cl('Exemplo conceitual')}<h2>${d[0]}</h2><p>${d[1]}</p><ol class="composition-flow">${d[2].map(n=>`<li>${n}</li>`).join('')}</ol></div></div>`}
function cBind(){let opener=null;const closeMenu=()=>{document.querySelectorAll('.mega-menu').forEach(m=>m.hidden=true);document.querySelectorAll('[data-menu]').forEach(b=>b.setAttribute('aria-expanded','false'));document.body.classList.remove('menu-open')};document.querySelectorAll('[data-menu]').forEach(b=>b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')==='true';closeMenu();if(!open){opener=b;document.getElementById('menu-'+b.dataset.menu).hidden=false;b.setAttribute('aria-expanded','true');document.body.classList.add('menu-open')}}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();opener?.focus()}if(e.key==='Tab'&&document.body.classList.contains('menu-open')){const items=[...document.querySelectorAll('.site-header a,.site-header button')].filter(x=>x.getClientRects().length);const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});document.addEventListener('click',e=>{if(!e.target.closest('.site-header'))closeMenu()});document.querySelectorAll('.mega-menu a').forEach(a=>a.addEventListener('click',closeMenu));document.querySelectorAll('.architecture-accordion details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.architecture-accordion details').forEach(x=>{if(x!==d)x.open=false})}));const query=document.getElementById('block-query');if(query){const cat=document.getElementById('category-query'),stage=document.getElementById('status-query');const filter=()=>{let count=0;document.querySelectorAll('[data-block]').forEach(el=>{const show=el.dataset.search.includes(query.value.toLowerCase().trim())&&(!cat.value||el.dataset.category===cat.value)&&(!stage.value||el.dataset.status===stage.value);el.hidden=!show;if(show)count++});document.getElementById('catalog-count').textContent=count+' capacidades encontradas';document.getElementById('empty-catalog').hidden=count>0};query.addEventListener('input',filter);cat.addEventListener('change',filter);stage.addEventListener('change',filter)}document.querySelectorAll('[data-composition]').forEach(b=>b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-composition]')];const i=tabs.indexOf(b);const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();tabs[next].click()}}));document.querySelectorAll('[data-composition]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-composition]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));document.getElementById('composition-example').innerHTML=cComposition(Number(b.dataset.composition))}));const film=document.getElementById('concept-film');if(film){document.querySelector('[data-open-film]').addEventListener('click',()=>{film.showModal();film.classList.remove('paused')});document.querySelector('[data-close-film]').addEventListener('click',()=>film.close());film.addEventListener('click',e=>{if(e.target===film)film.close()});document.querySelector('[data-toggle-film]').addEventListener('click',e=>{const paused=film.classList.toggle('paused');e.target.textContent=paused?'Reproduzir':'Pausar';e.target.setAttribute('aria-pressed',String(paused))})}const images=document.querySelectorAll('[data-image]');if(images.length){const dialog=document.createElement('dialog');dialog.className='image-dialog';dialog.innerHTML='<button aria-label="Fechar imagem">Fechar ×</button><img alt=""><p></p>';document.body.append(dialog);dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});images.forEach(b=>b.addEventListener('click',()=>{dialog.querySelector('img').src=b.dataset.image;dialog.querySelector('img').alt=b.dataset.caption;dialog.querySelector('p').textContent=b.dataset.caption;dialog.showModal()}))}if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.signal-art').forEach(el=>observer.observe(el))}}
if(typeof document!=='undefined'&&document.addEventListener)document.addEventListener('DOMContentLoaded',cBind);
